def canonical_schematic(data):
    return {"version":data.get("version"),"generator":data.get("generator"),"symbols":sorted([{"lib_id":x["lib_id"],"reference":x["reference"],"value":x["value"],"footprint":x.get("footprint",""),"x":round(x["x"],4),"y":round(x["y"],4),"rotation":round(x["rotation"],4)} for x in data.get("symbols",[])],key=lambda x:(x["reference"],x["lib_id"])),"wires":sorted([tuple((round(a,4),round(b,4)) for a,b in x["points"]) for x in data.get("wires",[])],key=repr),"labels":sorted((x["text"],round(x["x"],4),round(x["y"],4)) for x in data.get("labels",[])),"global_labels":sorted((x["text"],round(x["x"],4),round(x["y"],4)) for x in data.get("global_labels",[]))}
